#include <stdio.h>
#include <math.h>

typedef struct { float x,y,z; } V;
V add(V a,V b) { return (V){a.x+b.x,a.y+b.y,a.z+b.z}; }
V sub(V a,V b) { return (V){a.x-b.x,a.y-b.y,a.z-b.z}; }
V mul(V a,float s) { return (V){a.x*s,a.y*s,a.z*s}; }
float dot(V a,V b) { return a.x*b.x+a.y*b.y+a.z*b.z; }
V unit(V a) {
    float s=sqrt(dot(a,a));
    return (V){a.x/s,a.y/s,a.z/s};
}
/* Intersect the unit sphere centered at (0,-0.5,-5). */
float sphere(V o,V d) {
    V q=sub(o,(V){0,-.5f,-5});
    float a=dot(d,d), b=2*dot(q,d), c=dot(q,q)-1;
    float det=b*b-4*a*c;
    if(det<0) return -1;
    float t=(-b-sqrt(det))/(2*a);
    if(t<.001f) t=(-b+sqrt(det))/(2*a);
    return t<.001f ? -1:t;
}
V color(V d,V light) {
    V zero={0,0,0}, n,p;
    float s=sphere(zero,d), t=-1;
    if(fabs(d.y)>=.0001f) t=-1.5f/d.y;
    int ball=s>=.001f && (t<.001f || s<t);
    if(ball) {
        p=mul(d,s);
        n=unit(sub(p,(V){0,-.5f,-5}));
    } else if(t>=.001f) {
        p=mul(d,t); n=(V){0,1,0};
    } else {
        float u=.5f*(d.y+1);
        return add(mul((V){1,1,1},1-u),mul((V){.5f,.7f,1},u));
    }
    float shade=fmax(0,dot(n,light));
    if(sphere(add(p,mul(n,.001f)),unit(light))>0) shade=0;
    shade=.2f+(1-.2f)*shade;
    if(ball) return mul((V){1,.2f,.2f},shade);
    float v=(((int)(floor(p.x)+floor(p.z)))&1)==0 ? .9f:.4f;
    return mul((V){v,v,v},shade);
}
int main(void) {
    FILE *f=fopen("reconstructed.ppm","w");
    if(!f) return 1;
    fprintf(f,"P3\n2400 1800\n255\n");
    V light=unit((V){1,1,-1});
    float width=(2400.f/1800.f)*2.f;
    for(int y=0;y<1800;y++) for(int x=0;x<2400;x++) {
        float u=(float)x/2399, v=(float)y/1799;
        V d=unit(add((V){-width*.5f,-1,-1},
                     add((V){width*u,0,0},(V){0,2*(1-v),0})));
        V c=color(d,light);
        int r=255.99f*(float)fmin(1,fmax(0,c.x));
        int g=255.99f*(float)fmin(1,fmax(0,c.y));
        int b=255.99f*(float)fmin(1,fmax(0,c.z));
        fprintf(f,"%d %d %d\n",r,g,b);
    }
    return fclose(f)!=0;
}
